def icon(k):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[k]+'</svg>'
def head(title,desc):return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | MATES Foundation</title><meta name="description" content="{desc}"><meta name="theme-color" content="#062b4e"><meta property="og:title" content="{title} | MATES Foundation"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:image" content="https://ai4betterair.github.io/MATESFoundation/assets/mates-foundation-logo.png"><link rel="stylesheet" href="assets/style.css"><script src="assets/site.js" defer></script></head><body id="top"><a class="skip" href="#main">Skip to content</a><div class="topline"><div class="wrap"><span>A little care. A lasting difference.</span><span>Together for a Better Society</span></div></div><header><div class="wrap nav"><a class="brand" href="index.html" aria-label="MATES Foundation home"><img src="assets/mates-foundation-logo.png" alt="MATES Foundation — Together for a Better Society" width="1672" height="941"></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">Menu <span>☰</span></button><nav id="navigation" aria-label="Main navigation"><a href="about.html">Who we are</a><a href="team.html">Team</a><a href="initiatives.html">Our initiatives</a><a href="get-involved.html">Get involved</a><a href="contact.html">Contact</a><a class="button small" href="get-involved.html#support">Make a difference <span>↗</span></a></nav></div></header>'''
def footer():return '''<section class="closing"><div class="wrap closing-inner"><div><span class="eyebrow light">THE NEXT CHAPTER STARTS WITH US</span><h2>Good things happen<br>when we come together.</h2></div><a class="button white" href="get-involved.html">Find your way to help <span>↗</span></a></div></section><footer><div class="wrap footer-grid"><div><a class="brand footer-brand" href="index.html"><img src="assets/mates-foundation-logo.png" alt="MATES Foundation — Together for a Better Society" width="1672" height="941" loading="lazy"></a><p>People. Possibility. Positive change.<br>Together for a Better Society.</p></div><div><h3>Discover MATES</h3><a href="about.html">About the foundation</a><a href="team.html">Our team</a><a href="initiatives.html">Our initiatives</a><a href="about.html#values">Our values</a></div><div><h3>Be part of it</h3><a href="get-involved.html#volunteer">Volunteer</a><a href="get-involved.html#partner">Partner with us</a><a href="get-involved.html#support">Support our work</a><a href="contact.html">Get in touch</a></div></div><div class="wrap footer-bottom"><span>© <span id="year">2026</span> MATES Foundation. All rights reserved.</span><a href="privacy.html">Privacy & website information</a><a href="#top" class="back-top">Back to top ↑</a></div></footer></body></html>'''
def save(name,title,desc,body): (P/name).write_text(head(title,desc)+'<main id="main">'+body+'</main>'+footer())
def card(p):
 s,n,name,tag,desc,short,ic,focus,text=p
 return f'<a class="program-card" href="{s}.html"><div class="card-top"><span class="program-icon">{icon(ic)}</span><span class="number">{n} /</span></div><h3>{name}</h3><p>{desc}</p><span class="card-link">Explore initiative <span>↗</span></span></a>'
def intro(eye,title,text):return f'<section class="page-hero"><div class="wrap"><a class="breadcrumb" href="index.html">Home <span>/</span></a><span class="eyebrow">{eye}</span><h1>{title}</h1><p>{text}</p></div></section>'
